+const missions=[
+ {name:'A little nudge',eyebrow:'MISSION 01 · THE FIRST STEP',desc:'Bot is one tile away from the beacon. Give it a single, clear command.',w:4,h:4,start:[0,2],dir:0,goal:[3,2],stars:[],blocks:[],objectives:['Move Bot to the glowing beacon']},
