+];
+let mode='missions', level=0, pos=[0,2], dir=0, busy=false, moves=0, collected=0, switched=false, won=false, color=0xb6f278, sleepy=true, sandboxObjects=[], selectedItem='none', soundOn=false, turnIndex=0, anim=null;
