+function current(){return missions[level]}
+function onGrid(x,z){const m=current();return x>=0&&z>=0&&x<m.w&&z<m.h}
+function isBlocked(x,z){const m=current();return m.blocks.some(p=>p[0]===x&&p[1]===z)&&!(switched&&level===2)}
+function aimCamera(){const m=current(), d=Math.max(m.w,m.h);const a=Math.PI/4+cameraYaw;camera.position.set(Math.sin(a)*d*1.35, d*1.6/zoom, Math.cos(a)*d*1.35);camera.lookAt((m.w-1)/2,0,(m.h-1)/2)}
+function resize(){const r=wrap.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();aimCamera()}
+new ResizeObserver(resize).observe(wrap);
+function clear(g){while(g.children.length){const o=g.children.pop();if(o.geometry)o.geometry.dispose()}}
+function box(parent,x,y,z,sx,sy,sz,mat,round=false){let geo=new THREE.BoxGeometry(sx,sy,sz);let obj=new THREE.Mesh(geo,mat);obj.position.set(x,y,z);obj.castShadow=true;obj.receiveShadow=true;parent.add(obj);return obj}
+function cylinder(parent,x,y,z,r1,r2,h,mat,segments=12){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
+function sphere(parent,x,y,z,r,mat,scale=[1,1,1]){const o=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),mat);o.position.set(x,y,z);o.scale.set(...scale);o.castShadow=true;parent.add(o);return o}
+function buildScene(){clear(boardGroup);clear(itemGroup);clear(botGroup);const m=current(), pad=(Math.max(m.w,m.h)-3)*.65;world.position.set(-m.w/2+.5,0,-m.h/2+.5);const slab=box(boardGroup,(m.w-1)/2,-.18,(m.h-1)/2,m.w+.28,.34,m.h+.28,mats.edge);slab.receiveShadow=true;
+ for(let z=0;z<m.h;z++)for(let x=0;x<m.w;x++){const tile=box(boardGroup,x,-.015,z,.96,.08,.96,(x+z)%2?mats.tile:mats.tileAlt);tile.userData={tile:[x,z]};tile.name='tile';const edges=new THREE.EdgesGeometry(new THREE.BoxGeometry(.96,.08,.96));const line=new THREE.LineSegments(edges,new THREE.LineBasicMaterial({color:0xffffff,transparent:true,opacity:.055}));line.position.copy(tile.position);boardGroup.add(line);if(mode==='sandbox')tile.material=tile.material.clone(),tile.material.color.setHex(0x697568);}
+ const makeBeacon=(x,z)=>{const ring=new THREE.Mesh(new THREE.TorusGeometry(.3,.045,8,28),new THREE.MeshStandardMaterial({color:0xb6f278,emissive:0x6daa3b,emissiveIntensity:1.4}));ring.rotation.x=Math.PI/2;ring.position.set(x,.12,z);itemGroup.add(ring);const light=new THREE.PointLight(0xa6ff75,1.3,2.3);light.position.set(x,.45,z);itemGroup.add(light);cylinder(itemGroup,x,.045,z,.23,.23,.04,new THREE.MeshStandardMaterial({color:0x64775b,emissive:0x344c31}));};makeBeacon(...m.goal);
+ m.blocks.forEach(([x,z])=>{if(switched&&level===2)return;const b=box(itemGroup,x,.27,z,.68,.56,.68,mats.block);b.rotation.y=.12;box(itemGroup,x,.57,z,.52,.06,.52,new THREE.MeshStandardMaterial({color:0xa29070}));});
+ m.stars.forEach(([x,z],i)=>{if(collected>i)return;const st=new THREE.Mesh(new THREE.OctahedronGeometry(.25,0),mats.gold);st.position.set(x,.44,z);st.rotation.y=.3;itemGroup.add(st);const l=new THREE.PointLight(0xffcb70,.7,1.7);l.position.set(x,.5,z);itemGroup.add(l)});
+ if(m.switch){const [x,z]=m.switch;const base=cylinder(itemGroup,x,.08,z,.27,.27,.12,mats.dark);const button=cylinder(itemGroup,x,.22,z,.17,.17,.16,switched?mats.leaf:mats.gold);button.userData.switch=true;const lamp=sphere(itemGroup,x,.43,z,.065,switched?mats.leaf:mats.gold);}
