+ $('#objectives').innerHTML=(mode==='sandbox'?['Make something wonderful','Wander wherever you like']:m.objectives).map((text,i)=>{let done=mode==='sandbox'?false:level===0?won:level===1?i===0?collected>0:won: i===0?switched:won;return `<li class="${done?'done':''}">${text}</li>`}).join('');$('#missionCard').style.display=mode==='sandbox'?'none':'';$('#customCard').classList.toggle('show',mode==='sandbox');$$('.cmd').forEach(b=>b.disabled=busy||won&&mode==='missions');$$('.modebtn').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#mobileMove').textContent=busy?'BOT IS MOVING…':'ONE STEP AT A TIME';}
+function say(title,sub){const t=$('#toast');t.innerHTML=`<strong>${title}</strong><span>${sub}</span>`;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1750)}
