+function beep(freq=450,dur=.08){try{const ctx=new AudioContext(),o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=freq;o.connect(g);g.connect(ctx.destination);g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+dur);o.start();o.stop(ctx.currentTime+dur)}catch{}}
+function run(action){if(busy||won&&mode==='missions')return;busy=true;moves++;updateUI();if(soundOn)beep(390,.06);const startPos=[...pos],startDir=dir;let duration=420;
+ if(action==='left')dir=(dir+1)%4;else if(action==='right')dir=(dir+3)%4;else if(action==='forward'){const [dx,dz]=headings[dir],nx=pos[0]+dx,nz=pos[1]+dz;if(onGrid(nx,nz)&&!isBlocked(nx,nz)){pos=[nx,nz];anim={kind:'move',from:startPos,to:[...pos],t:0};}else{duration=300;say('Bump!','A little wall is in the way.')}}else if(action==='interact'){const m=current(),[dx,dz]=headings[dir],near=(a,b)=>Math.abs(pos[0]-a)+Math.abs(pos[1]-b)<=1; if(m.switch&&!switched&&near(...m.switch)){switched=true;say('Click! Gate is open.','Nice interacting, little bot.');buildScene()}else{duration=280;say('Nothing nearby yet.','Try getting a little closer.')}}
+ if(action==='left'||action==='right')anim={kind:'turn',from:startDir,to:dir,t:0};if(action==='forward'&&pos[0]!==startPos[0]||action==='forward'&&pos[1]!==startPos[1]){}else if(action!=='forward'&&action!=='left'&&action!=='right')anim=null;
+ setTimeout(()=>{busy=false;anim=null;if(mode==='missions'){const m=current();if(level===1&&m.stars.some(s=>s[0]===pos[0]&&s[1]===pos[1])&&collected===0){collected++;say('A star for Bot!','Found a little bit of sparkle.');buildScene()}if(pos[0]===m.goal[0]&&pos[1]===m.goal[1]&&(level!==1||collected>0)&&(level!==2||switched))complete();else updateUI()}else updateUI()},duration);
+}
